from commun_redaction import ROOT
def box(kind,title,text):return f'::: {kind} {title}\n{text}\n:::\n'
def section(number,title,text):return f'\n## {number}. {title}\n\n{text}\n'
def write(code,title,objectives,parts,sheet):
 d=next(ROOT.glob(f'{code:02}_*'))
 text='Titre: '+title+'\n<!-- optitab:1 -->\n'+box('objectifs','',objectives)
 for i,(heading,body) in enumerate(parts):text+=section(['I','II','III','IV','V','VI'][i],heading,body)
 def clean(value):
  value=value.replace(chr(9)+'imes',chr(92)+'times')
  value=value.replace('150div25','150'+chr(92)+'div25').replace('$widehat','$'+chr(92)+'widehat')
  return value.replace('$2,000+500=2,500$','$2000+500=2500$').replace('$1,200>950$','$1200>950$')
 (d/'cours_nouveau.txt').write_text(clean(text),encoding='utf-8')
 (d/'fiche_nouvelle.txt').write_text(clean('Titre: '+title+'\n<!-- optitab:1 -->\n'+sheet),encoding='utf-8')
B=box
write(11,'Longueurs et périmètres',
 'Choisir une unité, estimer et mesurer une longueur ; convertir en expliquant les relations ; comparer des longueurs et résoudre des problèmes de contour.',[
 ('Des unités adaptées',B('definition','Une longueur','Une longueur mesure une distance ou la taille d’un objet. Une estimation donne une valeur approchée avant de mesurer. On peut comparer à un repère connu : une gomme mesure quelques centimètres ; une porte environ deux mètres ; la distance entre deux villes s’exprime souvent en kilomètres.')+B('propriete','Les relations utiles','1 cm = 10 mm ; 1 dm = 10 cm ; 1 m = 10 dm = 100 cm ; 1 dam = 10 m ; 1 hm = 100 m ; 1 km = 1 000 m. Les symboles d’unités restent invariables : 3 cm, et non « 3 cms ».')),
 ('Convertir en raisonnant',B('methode','Changer d’unité','Dire d’abord la relation entre les deux unités. Pour convertir des mètres en centimètres, chaque mètre apporte 100 cm : on multiplie par 100. Pour convertir des centimètres en mètres, on regroupe les centimètres par 100. Il n’est pas nécessaire d’utiliser un tableau de conversion.')+B('exemple','Une même longueur',r'$3{,}5$ m représentent 3 m et un demi-mètre, soit $300+50=350$ cm. De même, 48 mm représentent 4 cm et 8 mm, soit $4{,}8$ cm. L’objet ne change pas de taille quand son unité change.')),
 ('Comparer et mesurer','[IMAGE_1]\n\n'+B('methode','Lire la règle','Placer le zéro à une extrémité et lire l’autre. Si le zéro n’est pas disponible, soustraire les deux lectures : de 15 mm à 68 mm, la longueur est $68-15=53$ mm. La graduation finale seule ne donne pas la longueur.')+B('exemple','Comparer avec la même unité',r'$0{,}5$ m = 50 cm ; donc $0{,}5$ m est plus long que 48 cm de 2 cm. Comparer directement les nombres 0,5 et 48 sans leurs unités n’a pas de sens.')),
 ('Parcourir le contour','[IMAGE_2]\n\n'+B('definition','Le périmètre','Le périmètre d’une figure est la longueur de son contour. Pour un polygone, additionner toutes les longueurs des côtés, exprimées dans la même unité. Sur le rectangle de 5 cm sur 3 cm : $5+3+5+3=16$ cm. On comprend ce calcul en suivant les quatre côtés ; aucune formule n’est à apprendre par cœur au CM1.')+B('attention','Contour et surface','Le périmètre s’exprime en unités de longueur. Il ne compte pas les carreaux à l’intérieur. Deux figures différentes peuvent avoir le même périmètre.')),
 ('Résoudre un problème de longueur',B('methode','Un jardin à clôturer','Dessiner un croquis, relever toutes les longueurs et choisir une unité commune. Calculer le contour entier, puis retirer le passage du portail. Si le grillage est vendu par rouleaux entiers, vérifier qu’on en achète assez : un reste dans une division peut imposer un rouleau supplémentaire.')+B('retenir','','Estimer, convertir, calculer puis contrôler : la réponse finale donne une longueur et son unité. Pour vérifier un partage, réunir toutes les parties et comparer au tout initial.'))
],B('retenir','','Périmètre = longueur du contour. Convertir avant d’additionner ou comparer des mesures de différentes unités.')+section('I','Relations utiles','1 cm = 10 mm ; 1 m = 100 cm ; 1 km = 1 000 m.\n\n1 dm = 10 cm ; 1 dam = 10 m ; 1 hm = 100 m.')+section('II','Méthodes',B('methode','Mesurer et convertir','Sur une règle décalée : fin − début. Pour convertir, utiliser la relation entre les unités : 3,5 m = 350 cm. Pour comparer, choisir une unité commune.'))+section('III','Problèmes',B('methode','Suivre le contour','Additionner chaque côté une fois. Pour une clôture : contour − portail. Pour un achat en rouleaux, vérifier que la longueur totale est suffisante.'))+B('attention','','Ne pas confondre contour et surface. Une mesure comprend toujours un nombre et une unité.'))

write(12,'Masses et contenances',
 'Distinguer masse et contenance ; choisir des repères ; convertir et comparer en raisonnant ; résoudre des problèmes de balance, de charge ou de partage.',[
 ('Deux grandeurs différentes',B('definition','Masse et contenance','La masse caractérise la quantité de matière d’un objet ; on la mesure avec une balance. La contenance indique ce qu’un récipient peut contenir. Une bouteille peut être décrite par sa contenance en litres et par sa masse en grammes : ces informations ne sont pas interchangeables.')+B('exemple','Des repères','Une gomme pèse quelques grammes, un cartable plusieurs kilogrammes, un camion plusieurs tonnes. Une cuillère contient quelques millilitres ; une canette environ 33 cL ; une baignoire peut contenir plus de 100 L. Ces repères aident à repérer une unité invraisemblable.')),
 ('Les unités de masse',B('propriete','Relations','1 g = 10 dg = 100 cg = 1 000 mg ; 1 kg = 10 hg = 100 dag = 1 000 g ; 1 t = 1 000 kg. Une même masse peut s’exprimer dans plusieurs unités.')+B('methode','Convertir une masse',r'Utiliser une relation connue plutôt qu’un tableau : $2{,}5$ kg = 2 kg + un demi-kilogramme, donc $2,000+500=2,500$ g. Pour comparer $1{,}2$ kg et 950 g, écrire 1 200 g puis comparer : $1,200>950$.')),
 ('Les unités de contenance',B('propriete','Relations','1 L = 10 dL = 100 cL = 1 000 mL ; 1 daL = 10 L ; 1 hL = 100 L. Un litre peut donc être partagé en cent portions d’un centilitre.')+B('exemple','Une carafe',r'Une carafe de $1{,}5$ L contient 150 cL. Un verre de 25 cL permet de former six parts : $150div25=6$. Vérification : $6	imes25=150$ cL.')),
 ('Lire une balance et une limite','[IMAGE_1]\n\n'+B('methode','Comparer des masses','Quand les plateaux d’une balance sont en équilibre, les masses sont égales. Un sac équilibré par 500 g, 200 g et 50 g a une masse de $500+200+50=750$ g. Ajouter toutes les masses présentes, y compris l’emballage si la situation le précise.')+B('attention','Ne pas dépasser une charge','Une capacité maximale est une limite à respecter. Convertir dans la même unité, additionner les personnes et les colis, puis comparer le total à la limite. Une charge égale à la limite est autorisée.')),
 ('Contrôler un partage',B('methode','Pots et récipients','Pour remplir des pots identiques, convertir d’abord la quantité disponible dans l’unité du pot. Calculer le nombre de pots complets et vérifier par multiplication. Si un reste apparaît, il ne suffit pas à remplir un nouveau pot entier.')+B('retenir','','Comparer une masse avec une masse, une contenance avec une contenance. Un kilogramme de plumes et un kilogramme de plomb ont la même masse ; leurs volumes peuvent être différents. Un litre d’eau a une masse proche d’un kilogramme, mais cette correspondance ne vaut pas pour tous les produits.'))
],B('retenir','','Masse : balance, grammes ou kilogrammes. Contenance : récipient, litres ou millilitres.')+section('I','Relations','1 kg = 1 000 g ; 1 g = 1 000 mg ; 1 t = 1 000 kg.\n\n1 L = 100 cL = 1 000 mL ; 1 cL = 10 mL ; 1 hL = 100 L.')+section('II','Calculer',B('methode','','Convertir dans une unité commune, effectuer le calcul, puis écrire l’unité. Une balance en équilibre indique des masses égales. Pour des pots identiques, partager puis contrôler par multiplication.'))+B('attention','','Ne pas mélanger litres et kilogrammes. Une charge maximale se compare à la masse totale, colis compris.'))

write(13,'Aires et angles : comparer',
 'Comparer et mesurer des surfaces par pavage ; utiliser le centimètre carré ; distinguer aire et périmètre ; nommer et comparer des angles avec un calque ou une équerre.',[
 ('Comparer des surfaces',B('definition','L’aire','L’aire mesure l’étendue d’une surface. Pour comparer deux surfaces avant toute mesure, on peut les superposer ou découper l’une en morceaux et les réassembler sur l’autre. Le découpage conserve l’aire si aucun morceau n’est perdu et si les morceaux ne se chevauchent pas.')+B('methode','Choisir une unité','Sur un quadrillage, choisir un carreau comme unité d’aire. Compter les carreaux entièrement recouverts et regrouper les demi-carreaux deux par deux. Comparer les figures avec des carreaux de même taille.')),
 ('Mesurer par pavage','[IMAGE_1]\n\n'+B('exemple','Une forme en L','Le rectangle contient trois rangées de quatre carreaux : $3\times4=12$ carreaux. On retire deux carreaux : $12-2=10$. La forme restante a donc une aire de 10 carreaux. Compter des rangées est plus rapide que recompter chaque carreau isolément.')+B('definition','Le centimètre carré','Le centimètre carré, noté cm², est l’aire d’un carré de 1 cm de côté. Si chaque carreau représente 1 cm², la forme en L précédente a une aire de 10 cm². L’unité carrée mesure une surface, pas une longueur.')),
 ('Distinguer aire et contour',B('attention','Deux questions différentes','Le périmètre suit le bord ; l’aire mesure l’intérieur. Une bande de 8 cm sur 1 cm couvre 8 carrés unités et son contour mesure $8+1+8+1=18$ cm. Un carré de 3 cm de côté couvre 9 carrés unités et son contour mesure $3+3+3+3=12$ cm. Le plus grand contour n’a donc pas toujours la plus grande aire.')+B('methode','Agrandir un carré','Si un côté de carré double, le nombre de carreaux double dans chaque rangée et le nombre de rangées double aussi. Le nouveau carré contient quatre petits carrés. Son aire ne double pas seulement. Au CM1, on justifie par le dessin et le pavage, sans mémoriser une formule d’aire.')),
 ('Un angle est une ouverture','[IMAGE_2]\n\n'+B('definition','Sommet et côtés',r'Un angle est une ouverture entre deux côtés issus d’un même sommet. Dans $widehat{ABC}$, le sommet est B : sa lettre est au milieu. Les côtés suivent les directions de B vers A et de B vers C. Prolonger les côtés ne change pas l’ouverture.')+B('methode','Comparer avec un calque','Décalquer un angle, puis superposer son sommet et un de ses côtés avec ceux de l’autre angle. Comparer les deux côtés restants. Le plus ouvert est le plus grand, quelle que soit l’orientation du dessin.')),
 ('L’angle droit comme repère',B('propriete','Le coin de l’équerre','L’équerre permet de reconnaître l’angle droit. Un angle peut être moins ouvert, aussi ouvert ou plus ouvert que cet angle repère. Au CM1, on compare les ouvertures sans rapporteur et sans mesure en degrés.')+B('retenir','','Pour une aire, compter des unités de surface. Pour un angle, comparer une ouverture. Le dessin, le calque et l’équerre servent à expliquer et à contrôler les réponses.'))
],B('retenir','','Aire : surface intérieure ; périmètre : contour. Pour comparer des aires, utiliser la même unité.')+section('I','Paver','Deux demi-carreaux forment un carreau. Un carré de 1 cm de côté représente 1 cm². Un découpage conserve l’aire si rien n’est perdu ni superposé.')+section('II','Comparer des angles',B('methode','','Superposer les sommets et un côté avec un calque. Comparer l’ouverture du second côté. Vérifier un angle droit avec l’équerre.'))+B('attention','',r'La longueur dessinée des côtés ne change pas l’angle. Dans $widehat{ABC}$, le sommet est B. Un plus grand périmètre ne garantit pas une plus grande aire.'))

write(14,'Horaires et durées',
 'Lire et placer les aiguilles ; convertir heures et minutes ; calculer une durée écoulée, une arrivée ou un départ ; interpréter un planning.',[
 ('Un horaire n’est pas une durée',B('definition','Instant et temps écoulé','Un horaire repère un instant : par exemple 14 h 30. Une durée mesure le temps entre deux instants : par exemple 45 min. Une activité peut commencer à 14 h 30 et durer 45 min ; son horaire de fin est alors 15 h 15.')+B('propriete','Les repères','1 h = 60 min ; 1 jour = 24 h. Les minutes ne se regroupent pas par cent : après 59 minutes, la minute suivante complète une nouvelle heure.')),
 ('Lire une horloge','[IMAGE_1]\n\n'+B('methode','Deux aiguilles à suivre','La petite aiguille indique l’heure ; la grande indique les minutes. Entre deux nombres consécutifs du cadran, il y a 5 minutes. Pour lire 8 h 20, la grande aiguille pointe vers 4 et la petite se trouve un peu après 8. Les deux aiguilles avancent progressivement.')+B('attention','Matin et après-midi','Le cadran recommence après douze heures. La même position peut représenter 8 h 20 du matin ou 20 h 20 le soir. Le contexte permet de choisir. Pour placer 16 h 45, mettre la grande aiguille sur 9 et la petite entre 4 et 5, proche de 5.')),
 ('Convertir et comparer',B('exemple','Former des heures','Pour convertir 95 min, former une heure de 60 min : $95=60+35$. Donc 95 min = 1 h 35 min. Pour convertir 2 h 05 min en minutes : $2\times60+5=125$ min.')+B('methode','Une unité commune','Pour comparer 1 h 15 min et 80 min, écrire $60+15=75$ min. Ainsi 80 min durent 5 min de plus. Un contrôle en minutes évite de confondre 1 h 15 et 1,15 h.')),
 ('Avancer pour trouver une durée','[IMAGE_2]\n\n'+B('methode','Passer par une heure ronde','Entre 9 h 40 et 10 h 15 : avancer de 20 min pour atteindre 10 h, puis de 15 min pour atteindre 10 h 15. Additionner : $20+15=35$ min. Une frise aide à placer les étapes dans le bon ordre.')+B('exemple','Un trajet plus long','Entre 9 h 40 et 11 h 15, ajouter l’heure de 10 h à 11 h : $20+60+15=95$ min, soit 1 h 35 min. Pour vérifier, ajouter cette durée à l’horaire de départ.')),
 ('Trouver une arrivée ou un départ',B('methode','Choisir le sens','Pour l’arrivée, avancer depuis le départ de la durée prévue. Pour le départ, reculer depuis l’arrivée souhaitée. Une marge pour arriver en avance se retire aussi à l’horaire souhaité ; elle ne change pas la durée de l’activité.')+B('attention','Horaires réguliers','Quatre horaires de départ successifs sont séparés par trois intervalles. Si un bus part à 7 h, 7 h 20, 7 h 40 et 8 h, le premier et le dernier départ sont espacés de 60 min, pas de 80 min.')+B('retenir','','Identifier ce qu’on cherche : un horaire ou une durée. Dessiner une frise, utiliser 60 min = 1 h et vérifier le sens du résultat.'))
],section('I','Relations','1 h = 60 min ; 1 jour = 24 h.\n\n95 min = 1 h 35 min ; 2 h 05 min = 125 min.')+section('II','Lire',B('methode','','Petite aiguille : heure. Grande aiguille : minutes, avec 5 minutes entre deux nombres. Le contexte distingue le matin et le soir.'))+section('III','Calculer',B('methode','','Durée écoulée : avancer du départ à l’arrivée par étapes. Arrivée : départ + durée. Départ : reculer de la durée depuis l’arrivée.'))+B('attention','','1 h 30 min = 90 min = 1,5 h. Ne pas traiter les minutes comme des centièmes d’heure. Quatre horaires successifs délimitent trois intervalles.'))

write(20,'Organiser et lire des données',
 'Recueillir des réponses ; organiser des effectifs ; lire un tableau simple ou à double entrée, des barres et une courbe ; résoudre et contrôler un problème à partir des données.',[
 ('Organiser une enquête',B('definition','Donnée et effectif','Une donnée est une information recueillie. L’effectif d’une catégorie est le nombre de réponses qui lui correspondent. Une enquête doit préciser la question, les personnes interrogées et les choix autorisés. Si chacun donne une seule réponse, la somme des effectifs doit retrouver le nombre de personnes.')+B('methode','Compter sans oubli','Lire la liste, faire une marque par réponse puis regrouper les marques par catégorie. Vérifier qu’aucune réponse n’a été comptée deux fois. Pour un fruit préféré, les catégories sont des fruits ; pour un nombre de frères et sœurs, les catégories sont des nombres.')),
 ('Lire un tableau',B('methode','Ligne et colonne','Lire les en-têtes avant les nombres. Dans un tableau à double entrée, croiser la bonne ligne et la bonne colonne. Un nombre de cases isolées, un total de ligne et un total de colonne répondent à trois questions différentes.')+'| Classe | Menu A | Menu B |\n|---|---|---|\n| CM1 | 17 | 8 |\n| CM2 | 14 | 12 |\n\n'+B('exemple','Prélèvement et calcul','14 élèves de CM2 choisissent le menu A. Le total du menu B est $8+12=20$ élèves. Le total CM1 est $17+8=25$ élèves. Ne pas additionner tous les nombres quand une seule case suffit.')),
 ('Lire des barres','[IMAGE_1]\n\n'+B('methode','Titre, catégories et échelle','Le diagramme représente des prêts fictifs de livres. Lire les jours sur l’axe horizontal et les nombres de prêts sur l’axe vertical. Ici, un intervalle vertical vaut 2 prêts. Mardi correspond à 8 prêts, et non à 4 parce que la barre franchit quatre intervalles.')+B('exemple','Résoudre une question','Le total sur trois jours est $4+8+6=18$ prêts. L’écart entre mardi et lundi est $8-4=4$ prêts. Choisir l’addition pour réunir des groupes, la soustraction pour comparer deux effectifs.')),
 ('Lire une évolution','[IMAGE_2]\n\n'+B('methode','Un point relie deux informations','La courbe donne une hauteur fictive de plante selon la semaine. Pour la semaine 3, rejoindre le point puis lire 12 cm sur l’axe vertical. De la semaine 1 à la semaine 4, la hauteur passe de 6 cm à 18 cm : la croissance est $18-6=12$ cm.')+B('attention','Mesure et interprétation','La courbe relie des mesures hebdomadaires. Elle ne donne pas la hauteur exacte de chaque jour. Toujours vérifier les unités et ne pas inventer une donnée absente.')),
 ('Construire et contrôler',B('methode','Présenter ses données','Choisir un titre, nommer les catégories et indiquer l’unité. Pour des barres, conserver une même largeur et une échelle régulière. Pour des points, placer chaque couple de données au bon croisement. Comparer ensuite chaque valeur au tableau initial.')+B('retenir','','Une réponse doit citer la donnée utile et expliquer le calcul éventuel. Le choix le plus fréquent ne représente pas forcément plus de la moitié des réponses. Les données des exercices de ce chapitre sont fictives.'))
],section('I','Organiser',B('methode','','Poser une question précise, compter chaque réponse une fois, construire un tableau et vérifier la somme des effectifs.'))+section('II','Lire','Tableau : croiser ligne et colonne.\n\nBarres : catégorie, hauteur et valeur d’un intervalle.\n\nCourbe : lire les deux axes et l’unité.')+section('III','Résoudre',B('methode','','Total : additionner les groupes concernés. Écart : soustraire les valeurs. Répondre avec l’unité et la catégorie demandée.'))+B('attention','','Ne pas confondre une case et un total. Le plus grand effectif n’est pas toujours une majorité. Ne pas déduire une valeur qui n’a pas été mesurée.'))

write(21,'Premiers pas vers le hasard',
 'Reconnaître une expérience aléatoire ; lister des résultats possibles ; distinguer impossible, certain et incertain ; comparer les chances, notamment à une chance sur deux.',[
 ('Le résultat n’est pas connu d’avance',B('definition','Une expérience aléatoire','Une expérience est aléatoire si on ne peut pas prévoir son résultat avec certitude. Lancer une pièce équilibrée ou tirer sans regarder un jeton dans un sac en sont des exemples. On peut connaître les résultats possibles sans savoir lequel se produira.')+B('definition','Un évènement','Un évènement est une condition sur le résultat : « obtenir un nombre pair » avec un dé, par exemple. Il est impossible si aucun résultat ne convient ; certain si tous les résultats conviennent ; incertain dans les autres cas.')),
 ('Recenser les possibilités',B('methode','Lister sans oublier','Avec un dé classique, les résultats sont 1, 2, 3, 4, 5 et 6. Obtenir 7 est impossible ; obtenir un nombre inférieur à 7 est certain ; obtenir 2 est possible mais pas certain. Avant de comparer les chances, expliquer comment l’expérience est réalisée.')+B('propriete','Équilibre','Un dé équilibré donne la même chance à chacune de ses faces. Des jetons identiques au toucher, mélangés puis tirés sans regarder, ont la même chance d’être pris. Des couleurs présentes en quantités différentes n’ont pas nécessairement la même chance.')),
 ('Une chance sur deux',B('exemple','Deux groupes de même taille','Un dé équilibré possède trois faces paires, 2, 4 et 6, et trois faces impaires, 1, 3 et 5. Il y a autant de résultats qui réalisent « obtenir un nombre pair » que de résultats qui ne le réalisent pas. Cet évènement a une chance sur deux de se produire.')+B('exemple','Cartes et pièce','Avec une pièce équilibrée, pile et face ont la même chance. Dans un jeu de 32 cartes, 16 cartes sont rouges et 16 sont noires : tirer une rouge a une chance sur deux si les cartes sont bien mélangées et tirées au hasard.')),
 ('Comparer les chances','[IMAGE_1]\n\n'+B('methode','Comparer des groupes','La roue possède huit secteurs égaux : quatre « perdu », trois « bonbon » et un « peluche ». Gagner un lot correspond à quatre secteurs, comme perdre. Bonbon est plus probable que peluche, car trois secteurs donnent un bonbon contre un seul pour la peluche.')+B('definition','Peu probable et probable','Un évènement peu probable a moins d’une chance sur deux de se réaliser : il est plus facile qu’il ne se réalise pas. Un évènement probable a plus d’une chance sur deux. Ni l’un ni l’autre n’est garanti.')),
 ('Se méfier des fausses certitudes',B('attention','Deux mots ne suffisent pas','Un sac peut contenir un jeton rouge et trois bleus. Même si on peut annoncer « rouge ou bleu », le bleu est plus probable car il y a plus de jetons bleus. De même, « gagner ou perdre » ne signifie pas automatiquement une chance sur deux.')+B('retenir','','Lister les possibilités, vérifier si elles ont la même chance, puis comparer les groupes favorables et défavorables. Une série de résultats observés ne permet pas de garantir le résultat du prochain lancer.'))
],section('I','Vocabulaire','Impossible : aucun résultat favorable.\n\nCertain : tous les résultats conviennent.\n\nAléatoire : résultat non prévisible avec certitude.')+section('II','Comparer',B('methode','','Si les possibilités ont la même chance, comparer celles qui réalisent l’évènement aux autres. Deux groupes de même taille donnent une chance sur deux. Moins de possibilités favorables : peu probable ; davantage : probable.'))+B('attention','','Deux résultats annoncés ne signifient pas deux chances égales. Vérifier les quantités de jetons, les tailles des secteurs et l’équilibre du matériel.'))
